SET NAMES utf8mb4;

-- View: view_akun_hirarki
DROP VIEW IF EXISTS `view_akun_hirarki`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_akun_hirarki` AS
with recursive akun_hirarki as (select `a`.`id` AS `id`,`a`.`no_akun` AS `no_akun`,`a`.`nama` AS `nama`,`a`.`tipe_akun` AS `tipe_akun`,`a`.`kategori` AS `kategori`,`a`.`saldo_normal` AS `saldo_normal`,`a`.`parent_id` AS `parent_id`,1 AS `level`,cast(lpad(`a`.`no_akun`,10,'0') as char(1000) charset utf8mb4) AS `sort_path` from `m_akun_gl` `a` where `a`.`parent_id` is null union all select `a`.`id` AS `id`,`a`.`no_akun` AS `no_akun`,`a`.`nama` AS `nama`,`a`.`tipe_akun` AS `tipe_akun`,`a`.`kategori` AS `kategori`,`a`.`saldo_normal` AS `saldo_normal`,`a`.`parent_id` AS `parent_id`,`h`.`level` + 1 AS `level`,cast(concat(`h`.`sort_path`,'.',lpad(`a`.`no_akun`,10,'0')) as char(1000) charset utf8mb4) AS `sort_path` from (`m_akun_gl` `a` join `akun_hirarki` `h` on(`a`.`parent_id` = `h`.`id`)))select `akun_hirarki`.`id` AS `id`,`akun_hirarki`.`no_akun` AS `no_akun`,`akun_hirarki`.`nama` AS `nama`,`akun_hirarki`.`tipe_akun` AS `tipe_akun`,`akun_hirarki`.`kategori` AS `kategori`,`akun_hirarki`.`saldo_normal` AS `saldo_normal`,`akun_hirarki`.`parent_id` AS `parent_id`,`akun_hirarki`.`level` AS `level`,`akun_hirarki`.`sort_path` AS `sort_path` from `akun_hirarki`;

-- View: view_akun_transaksi_only
DROP VIEW IF EXISTS `view_akun_transaksi_only`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_akun_transaksi_only` AS
with recursive akun_path as (select `m_akun_gl`.`id` AS `id`,`m_akun_gl`.`no_akun` AS `no_akun`,`m_akun_gl`.`nama` AS `nama`,`m_akun_gl`.`parent_id` AS `parent_id`,concat(`m_akun_gl`.`no_akun`,' - ',`m_akun_gl`.`nama`) AS `full_path` from `m_akun_gl` where `m_akun_gl`.`parent_id` is null union all select `a`.`id` AS `id`,`a`.`no_akun` AS `no_akun`,`a`.`nama` AS `nama`,`a`.`parent_id` AS `parent_id`,concat(`p`.`full_path`,' / ',`a`.`no_akun`,' - ',`a`.`nama`) AS `full_path` from (`m_akun_gl` `a` join `akun_path` `p` on(`a`.`parent_id` = `p`.`id`)))select `ap`.`id` AS `id`,`ap`.`no_akun` AS `no_akun`,`ap`.`nama` AS `nama`,`ap`.`parent_id` AS `parent_id`,`ap`.`full_path` AS `full_path` from (`akun_path` `ap` left join `m_akun_gl` `c` on(`c`.`parent_id` = `ap`.`id`)) where `c`.`id` is null;

-- View: view_daftar_hutang
DROP VIEW IF EXISTS `view_daftar_hutang`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_daftar_hutang` AS
select `j`.`id` AS `jurnal_id`,`j`.`kode_jurnal` AS `kode_jurnal`,`j`.`no_invoice` AS `no_invoice`,`j`.`tanggal` AS `tanggal`,`j`.`keterangan` AS `keterangan`,`j`.`entitas_id` AS `entitas_id`,`j`.`partner_id` AS `partner_id`,`p`.`nama` AS `partner_nama`,`h`.`akun_hutang_id` AS `akun_hutang_id`,`h`.`nama_akun_hutang` AS `nama_akun_hutang`,coalesce(`h`.`total_hutang`,0) AS `total_tagihan`,coalesce(`pl`.`total_pelunasan`,0) AS `total_pelunasan`,coalesce(`h`.`total_hutang`,0) - coalesce(`pl`.`total_pelunasan`,0) AS `sisa_hutang`,to_days(curdate()) - to_days(`j`.`tanggal`) AS `umur_hutang` from (((`jurnal_header` `j` join (select `jd`.`jurnal_id` AS `jurnal_id`,`jd`.`akun_id` AS `akun_hutang_id`,`a`.`nama` AS `nama_akun_hutang`,sum(`jd`.`kredit`) AS `total_hutang` from (`jurnal_detail` `jd` join `m_akun_gl` `a` on(`a`.`id` = `jd`.`akun_id` and `a`.`kategori` = 'hutang')) where `jd`.`kredit` > 0 group by `jd`.`jurnal_id`,`jd`.`akun_id`,`a`.`nama`) `h` on(`h`.`jurnal_id` = `j`.`id`)) left join (select `ph`.`jurnal_hutang_id` AS `jurnal_hutang_id`,sum(`ph`.`jumlah`) AS `total_pelunasan` from (`pelunasan_hutang` `ph` join `jurnal_header` `jk` on(`jk`.`id` = `ph`.`jurnal_kas_id` and `jk`.`status` = 'posted')) group by `ph`.`jurnal_hutang_id`) `pl` on(`pl`.`jurnal_hutang_id` = `j`.`id`)) left join `m_partner` `p` on(`p`.`id` = `j`.`partner_id`)) where `j`.`status` = 'posted' and coalesce(`h`.`total_hutang`,0) > 0 having `sisa_hutang` > 0;

-- View: view_aging_hutang
DROP VIEW IF EXISTS `view_aging_hutang`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_aging_hutang` AS
select `dh`.`partner_id` AS `partner_id`,`dh`.`partner_nama` AS `partner_nama`,`dh`.`entitas_id` AS `entitas_id`,`dh`.`akun_hutang_id` AS `akun_hutang_id`,`a`.`no_akun` AS `akun_kode`,`a`.`nama` AS `akun_nama`,`a`.`kategori` AS `akun_kategori`,sum(case when `dh`.`umur_hutang` between 0 and 14 then `dh`.`sisa_hutang` else 0 end) AS `aging_0_14`,sum(case when `dh`.`umur_hutang` between 15 and 30 then `dh`.`sisa_hutang` else 0 end) AS `aging_15_30`,sum(case when `dh`.`umur_hutang` between 31 and 45 then `dh`.`sisa_hutang` else 0 end) AS `aging_31_45`,sum(case when `dh`.`umur_hutang` between 46 and 60 then `dh`.`sisa_hutang` else 0 end) AS `aging_46_60`,sum(case when `dh`.`umur_hutang` > 60 then `dh`.`sisa_hutang` else 0 end) AS `aging_60_plus`,sum(`dh`.`sisa_hutang`) AS `total_hutang` from (`view_daftar_hutang` `dh` join `m_akun_gl` `a` on(`a`.`id` = `dh`.`akun_hutang_id`)) group by `dh`.`partner_id`,`dh`.`partner_nama`,`dh`.`entitas_id`,`dh`.`akun_hutang_id`,`a`.`no_akun`,`a`.`nama`,`a`.`kategori`;

-- View: view_daftar_piutang
DROP VIEW IF EXISTS `view_daftar_piutang`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_daftar_piutang` AS
select `j`.`id` AS `jurnal_id`,`j`.`kode_jurnal` AS `kode_jurnal`,`j`.`no_invoice` AS `no_invoice`,`j`.`tanggal` AS `tanggal`,`j`.`keterangan` AS `keterangan`,`j`.`entitas_id` AS `entitas_id`,`j`.`cabang_id` AS `cabang_id`,`j`.`partner_id` AS `partner_id`,`p`.`nama` AS `partner_nama`,`p`.`is_vendor` AS `is_vendor`,`p`.`is_customer` AS `is_customer`,coalesce(`dp`.`total_piutang`,0) AS `total_tagihan`,coalesce(sum(case when `jk`.`status` = 'posted' then `pp`.`jumlah` else 0 end),0) AS `total_pelunasan`,coalesce(`dp`.`total_piutang`,0) - coalesce(sum(case when `jk`.`status` = 'posted' then `pp`.`jumlah` else 0 end),0) AS `sisa_piutang`,to_days(curdate()) - to_days(`j`.`tanggal`) AS `umur_piutang` from ((((`jurnal_header` `j` join (select `d`.`jurnal_id` AS `jurnal_id`,sum(`d`.`debit`) AS `total_piutang` from (`jurnal_detail` `d` join `m_akun_gl` `a2` on(`a2`.`id` = `d`.`akun_id`)) where `a2`.`kategori` = 'piutang' group by `d`.`jurnal_id`) `dp` on(`dp`.`jurnal_id` = `j`.`id`)) left join `pelunasan_piutang` `pp` on(`pp`.`jurnal_piutang_id` = `j`.`id`)) left join `jurnal_header` `jk` on(`jk`.`id` = `pp`.`jurnal_kas_id`)) left join `m_partner` `p` on(`p`.`id` = `j`.`partner_id`)) where `j`.`status` = 'posted' and coalesce(`dp`.`total_piutang`,0) > 0 and !exists(select 1 from `pelunasan_piutang` `pp2` where `pp2`.`jurnal_kas_id` = `j`.`id` limit 1) group by `j`.`id`,`j`.`kode_jurnal`,`j`.`no_invoice`,`j`.`tanggal`,`j`.`keterangan`,`j`.`entitas_id`,`j`.`cabang_id`,`j`.`partner_id`,`p`.`nama`,`p`.`is_vendor`,`p`.`is_customer`,`dp`.`total_piutang` having `sisa_piutang` > 0;

-- View: view_aging_piutang
DROP VIEW IF EXISTS `view_aging_piutang`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_aging_piutang` AS
select `view_daftar_piutang`.`partner_id` AS `partner_id`,max(`view_daftar_piutang`.`partner_nama`) AS `partner_nama`,`view_daftar_piutang`.`entitas_id` AS `entitas_id`,max(`view_daftar_piutang`.`is_vendor`) AS `is_vendor`,max(`view_daftar_piutang`.`is_customer`) AS `is_customer`,sum(case when `view_daftar_piutang`.`umur_piutang` between 0 and 14 then `view_daftar_piutang`.`sisa_piutang` else 0 end) AS `aging_0_14`,sum(case when `view_daftar_piutang`.`umur_piutang` between 15 and 30 then `view_daftar_piutang`.`sisa_piutang` else 0 end) AS `aging_15_30`,sum(case when `view_daftar_piutang`.`umur_piutang` between 31 and 45 then `view_daftar_piutang`.`sisa_piutang` else 0 end) AS `aging_31_45`,sum(case when `view_daftar_piutang`.`umur_piutang` between 46 and 60 then `view_daftar_piutang`.`sisa_piutang` else 0 end) AS `aging_46_60`,sum(case when `view_daftar_piutang`.`umur_piutang` > 60 then `view_daftar_piutang`.`sisa_piutang` else 0 end) AS `aging_60_plus`,sum(`view_daftar_piutang`.`sisa_piutang`) AS `total_piutang` from `view_daftar_piutang` group by `view_daftar_piutang`.`partner_id`,`view_daftar_piutang`.`entitas_id`;

-- View: view_daftar_uang_muka
DROP VIEW IF EXISTS `view_daftar_uang_muka`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_daftar_uang_muka` AS
select `j`.`id` AS `jurnal_id`,`j`.`kode_jurnal` AS `kode_jurnal`,`j`.`keterangan` AS `keterangan`,`j`.`cabang_id` AS `cabang_id`,`j`.`tanggal` AS `tanggal`,`j`.`entitas_id` AS `entitas_id`,`e`.`nama` AS `entitas_nama`,`j`.`partner_id` AS `partner_id`,`p`.`nama` AS `partner_nama`,sum(case when `d`.`akun_id` in (select `m_akun_gl`.`id` from `m_akun_gl` where `m_akun_gl`.`kategori` = 'uang_muka') then `d`.`debit` else 0 end) AS `nominal`,coalesce((select sum(`pu`.`jumlah`) from `pelunasan_uang_muka` `pu` where `pu`.`jurnal_uang_muka_id` = `j`.`id`),0) AS `terpakai`,sum(case when `d`.`akun_id` in (select `m_akun_gl`.`id` from `m_akun_gl` where `m_akun_gl`.`kategori` = 'uang_muka') then `d`.`debit` else 0 end) - coalesce((select sum(`pu`.`jumlah`) from `pelunasan_uang_muka` `pu` where `pu`.`jurnal_uang_muka_id` = `j`.`id`),0) AS `sisa`,to_days(curdate()) - to_days(`j`.`tanggal`) AS `umur`,case when sum(case when `d`.`akun_id` in (select `m_akun_gl`.`id` from `m_akun_gl` where `m_akun_gl`.`kategori` = 'uang_muka') then `d`.`debit` else 0 end) - coalesce((select sum(`pu`.`jumlah`) from `pelunasan_uang_muka` `pu` where `pu`.`jurnal_uang_muka_id` = `j`.`id`),0) <= 0 then 'closed' else 'open' end AS `status` from (((`jurnal_header` `j` join `jurnal_detail` `d` on(`d`.`jurnal_id` = `j`.`id`)) left join `m_partner` `p` on(`p`.`id` = `j`.`partner_id`)) left join `m_entitas` `e` on(`e`.`id` = `j`.`entitas_id`)) where `j`.`jenis` = 'JKK' and `j`.`status` = 'posted' and exists(select 1 from `jurnal_detail` `d2` where `d2`.`jurnal_id` = `j`.`id` and `d2`.`akun_id` in (select `m_akun_gl`.`id` from `m_akun_gl` where `m_akun_gl`.`kategori` = 'uang_muka') limit 1) group by `j`.`id`,`j`.`kode_jurnal`,`j`.`keterangan`,`j`.`tanggal`,`j`.`entitas_id`,`e`.`nama`,`j`.`cabang_id`,`j`.`partner_id`,`p`.`nama`;

-- View: view_aging_uang_muka
DROP VIEW IF EXISTS `view_aging_uang_muka`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_aging_uang_muka` AS
select `x`.`entitas_id` AS `entitas_id`,`x`.`entitas_nama` AS `entitas_nama`,`x`.`cabang_id` AS `cabang_id`,`x`.`partner_id` AS `partner_id`,`x`.`partner_nama` AS `partner_nama`,sum(case when `x`.`umur` between 0 and 7 then `x`.`sisa` else 0 end) AS `aging_0_7`,sum(case when `x`.`umur` between 8 and 14 then `x`.`sisa` else 0 end) AS `aging_8_14`,sum(case when `x`.`umur` between 15 and 30 then `x`.`sisa` else 0 end) AS `aging_15_30`,sum(case when `x`.`umur` > 30 then `x`.`sisa` else 0 end) AS `aging_30_up`,sum(`x`.`sisa`) AS `total_sisa` from `view_daftar_uang_muka` `x` where `x`.`sisa` > 0 and `x`.`status` = 'open' group by `x`.`entitas_id`,`x`.`entitas_nama`,`x`.`cabang_id`,`x`.`partner_id`,`x`.`partner_nama`;

-- View: view_laporan_keuangan
DROP VIEW IF EXISTS `view_laporan_keuangan`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_laporan_keuangan` AS
with saldo_akun as (select `b`.`akun_id` AS `akun_id`,`a`.`saldo_normal` AS `saldo_normal`,min(`b`.`tanggal`) AS `tanggal_awal`,max(`b`.`tanggal`) AS `tanggal_akhir`,sum(`b`.`debit`) AS `total_debit`,sum(`b`.`kredit`) AS `total_kredit`,sum(case when `a`.`saldo_normal` = 'debet' then `b`.`debit` - `b`.`kredit` when `a`.`saldo_normal` = 'kredit' then `b`.`kredit` - `b`.`debit` else 0 end) AS `saldo_akhir` from ((`buku_besar` `b` join `jurnal_header` `j` on(`j`.`id` = `b`.`jurnal_id`)) join `m_akun_gl` `a` on(`a`.`id` = `b`.`akun_id`)) where `j`.`status` = 'posted' group by `b`.`akun_id`,`a`.`saldo_normal`), saldo_hirarki as (select `h`.`id` AS `akun_id`,`h`.`no_akun` AS `no_akun`,`h`.`nama` AS `akun_nama`,`h`.`tipe_akun` AS `tipe_akun`,`h`.`kategori` AS `kategori`,`h`.`saldo_normal` AS `saldo_normal`,`h`.`parent_id` AS `parent_id`,`h`.`level` AS `level`,`h`.`sort_path` AS `sort_path`,`s`.`tanggal_awal` AS `tanggal_awal`,`s`.`tanggal_akhir` AS `tanggal_akhir`,coalesce(`s`.`total_debit`,0) AS `total_debit`,coalesce(`s`.`total_kredit`,0) AS `total_kredit`,coalesce(`s`.`saldo_akhir`,0) AS `saldo_sendiri` from (`view_akun_hirarki` `h` left join `saldo_akun` `s` on(`s`.`akun_id` = `h`.`id`))), subtotal as (select `p`.`akun_id` AS `akun_id`,`p`.`no_akun` AS `no_akun`,`p`.`akun_nama` AS `akun_nama`,`p`.`tipe_akun` AS `tipe_akun`,`p`.`kategori` AS `kategori`,`p`.`saldo_normal` AS `saldo_normal`,`p`.`parent_id` AS `parent_id`,`p`.`level` AS `level`,`p`.`sort_path` AS `sort_path`,min(`c`.`tanggal_awal`) AS `tanggal_awal`,max(`c`.`tanggal_akhir`) AS `tanggal_akhir`,sum(`c`.`total_debit`) AS `total_debit`,sum(`c`.`total_kredit`) AS `total_kredit`,sum(`c`.`saldo_sendiri`) AS `saldo_total` from (`saldo_hirarki` `p` left join `saldo_hirarki` `c` on(`c`.`sort_path` like concat(`p`.`sort_path`,'%'))) group by `p`.`akun_id`,`p`.`no_akun`,`p`.`akun_nama`,`p`.`tipe_akun`,`p`.`kategori`,`p`.`saldo_normal`,`p`.`parent_id`,`p`.`level`,`p`.`sort_path`)select `subtotal`.`akun_id` AS `akun_id`,`subtotal`.`no_akun` AS `no_akun`,`subtotal`.`akun_nama` AS `akun_nama`,`subtotal`.`tipe_akun` AS `tipe_akun`,`subtotal`.`kategori` AS `kategori`,`subtotal`.`saldo_normal` AS `saldo_normal`,`subtotal`.`parent_id` AS `parent_id`,`subtotal`.`level` AS `level`,`subtotal`.`sort_path` AS `sort_path`,`subtotal`.`tanggal_awal` AS `tanggal_awal`,`subtotal`.`tanggal_akhir` AS `tanggal_akhir`,`subtotal`.`total_debit` AS `total_debit`,`subtotal`.`total_kredit` AS `total_kredit`,`subtotal`.`saldo_total` AS `saldo_akhir` from `subtotal` order by `subtotal`.`sort_path`;

-- View: view_monitoring_piutang
DROP VIEW IF EXISTS `view_monitoring_piutang`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_monitoring_piutang` AS
select `jp`.`jurnal_piutang_id` AS `jurnal_piutang_id`,`jp`.`no_invoice` AS `invoice`,`jp`.`keterangan` AS `deskripsi`,`jp`.`entitas` AS `entitas`,`jp`.`partner` AS `partner`,`jp`.`entitas_id` AS `entitas_id`,`jp`.`cabang_id` AS `cabang_id`,`jp`.`partner_id` AS `partner_id`,`jp`.`cabang` AS `cabang`,`jp`.`kode_jurnal_piutang` AS `kode_jurnal_piutang`,`jp`.`tanggal_piutang` AS `tanggal_piutang`,`jp`.`jumlah_piutang` AS `jumlah_piutang`,`pp`.`id` AS `pelunasan_piutang_id`,`jkm`.`id` AS `jurnal_kas_id`,`jkm`.`kode_jurnal` AS `kode_jurnal_pelunasan`,`pp`.`jumlah` AS `jumlah_pelunasan`,`jkm`.`tanggal` AS `tanggal_pelunasan` from (((select `jh`.`id` AS `jurnal_piutang_id`,`jh`.`no_invoice` AS `no_invoice`,`jh`.`keterangan` AS `keterangan`,`jh`.`kode_jurnal` AS `kode_jurnal_piutang`,`jh`.`tanggal` AS `tanggal_piutang`,`jh`.`entitas_id` AS `entitas_id`,`jh`.`partner_id` AS `partner_id`,`jh`.`cabang_id` AS `cabang_id`,`me`.`nama` AS `entitas`,`mp`.`nama` AS `partner`,`mc`.`nama` AS `cabang`,sum(case when `mag`.`kategori` = 'piutang' then `jd`.`debit` else 0 end) AS `jumlah_piutang` from (((((`jurnal_header` `jh` join `jurnal_detail` `jd` on(`jd`.`jurnal_id` = `jh`.`id`)) join `m_akun_gl` `mag` on(`mag`.`id` = `jd`.`akun_id`)) left join `m_entitas` `me` on(`me`.`id` = `jh`.`entitas_id`)) left join `m_partner` `mp` on(`mp`.`id` = `jh`.`partner_id`)) left join `m_cabang` `mc` on(`mc`.`id` = `jh`.`cabang_id`)) where `jh`.`jenis` = 'JP' and `jh`.`status` = 'posted' and `mag`.`kategori` = 'piutang' group by `jh`.`id`,`jh`.`no_invoice`,`jh`.`keterangan`,`jh`.`kode_jurnal`,`jh`.`tanggal`,`jh`.`entitas_id`,`jh`.`partner_id`,`jh`.`cabang_id`,`me`.`nama`,`mp`.`nama`,`mc`.`nama`) `jp` left join `pelunasan_piutang` `pp` on(`pp`.`jurnal_piutang_id` = `jp`.`jurnal_piutang_id`)) left join `jurnal_header` `jkm` on(`jkm`.`id` = `pp`.`jurnal_kas_id` and `jkm`.`jenis` in ('JKM','JN') and `jkm`.`status` = 'posted'));

-- View: view_uang_muka_per_akun
DROP VIEW IF EXISTS `view_uang_muka_per_akun`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `view_uang_muka_per_akun` AS
select `j`.`id` AS `jurnal_id`,`j`.`kode_jurnal` AS `kode_jurnal`,`j`.`keterangan` AS `keterangan`,`j`.`tanggal` AS `tanggal`,`c`.`nama` AS `cabang_nama`,`j`.`cabang_id` AS `cabang_id`,`j`.`entitas_id` AS `entitas_id`,`e`.`nama` AS `entitas_nama`,`j`.`partner_id` AS `partner_id`,`p`.`nama` AS `partner_nama`,`d`.`akun_id` AS `akun_uang_muka_id`,concat(`a`.`no_akun`,' - ',`a`.`nama`) AS `akun_uang_muka`,sum(`d`.`debit`) AS `nominal`,coalesce((select sum(`pu`.`jumlah`) from `pelunasan_uang_muka` `pu` where `pu`.`jurnal_uang_muka_id` = `j`.`id` and `pu`.`akun_biaya_id` = `d`.`akun_id`),0) AS `terpakai`,sum(`d`.`debit`) - coalesce((select sum(`pu`.`jumlah`) from `pelunasan_uang_muka` `pu` where `pu`.`jurnal_uang_muka_id` = `j`.`id` and `pu`.`akun_biaya_id` = `d`.`akun_id`),0) AS `sisa`,to_days(curdate()) - to_days(`j`.`tanggal`) AS `umur`,case when sum(`d`.`debit`) - coalesce((select sum(`pelunasan_uang_muka`.`jumlah`) from `pelunasan_uang_muka` where `pelunasan_uang_muka`.`jurnal_uang_muka_id` = `j`.`id` and `pelunasan_uang_muka`.`akun_biaya_id` = `d`.`akun_id`),0) <= 0 then 'closed' else 'open' end AS `status` from (((((`jurnal_header` `j` join `jurnal_detail` `d` on(`d`.`jurnal_id` = `j`.`id`)) join `m_akun_gl` `a` on(`a`.`id` = `d`.`akun_id`)) left join `m_cabang` `c` on(`c`.`id` = `j`.`cabang_id`)) left join `m_partner` `p` on(`p`.`id` = `j`.`partner_id`)) left join `m_entitas` `e` on(`e`.`id` = `j`.`entitas_id`)) where `j`.`jenis` = 'JKK' and `j`.`status` = 'posted' and `a`.`kategori` = 'uang_muka' group by `j`.`id`,`j`.`kode_jurnal`,`j`.`keterangan`,`j`.`tanggal`,`j`.`entitas_id`,`c`.`nama`,`e`.`nama`,`j`.`cabang_id`,`j`.`partner_id`,`p`.`nama`,`d`.`akun_id`,`a`.`no_akun`,`a`.`nama`;

-- View: vw_detail_pelunasan_uang_muka
DROP VIEW IF EXISTS `vw_detail_pelunasan_uang_muka`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_detail_pelunasan_uang_muka` AS
select `p`.`id` AS `pelunasan_id`,`p`.`jurnal_uang_muka_id` AS `jurnal_uang_muka_id`,`jkk`.`kode_jurnal` AS `kode_jurnal_jkk`,`jkk`.`tanggal` AS `tanggal_jkk`,`jkk`.`keterangan` AS `keterangan_jkk`,`jkk`.`entitas_id` AS `entitas_id`,`jkk`.`partner_id` AS `partner_id`,`jkk`.`cabang_id` AS `cabang_jkk`,`jkk`.`status` AS `status_jkk`,`p`.`jurnal_biaya_id` AS `jurnal_biaya_id`,`jp`.`kode_jurnal` AS `kode_jurnal_biaya`,`jp`.`tanggal` AS `tanggal_biaya`,`jp`.`tanggal_invoice` AS `tanggal_invoice`,`jp`.`no_invoice` AS `no_invoice`,`jp`.`keterangan` AS `keterangan_biaya`,`jp`.`cabang_id` AS `cabang_biaya`,`jp`.`status` AS `status_biaya`,`p`.`akun_biaya_id` AS `akun_biaya_id`,`akun`.`no_akun` AS `no_akun_biaya`,`akun`.`nama` AS `nama_akun_biaya`,`akun`.`tipe_akun` AS `tipe_akun_biaya`,`akun`.`kategori` AS `kategori_akun_biaya`,`akun`.`saldo_normal` AS `saldo_normal_akun_biaya`,coalesce(`jd`.`total_debit`,0) AS `debit_biaya`,coalesce(`jd`.`total_kredit`,0) AS `kredit_biaya`,`p`.`jumlah` AS `jumlah_pelunasan`,`p`.`created_at` AS `created_at_pelunasan`,`p`.`updated_at` AS `updated_at_pelunasan` from ((((`pelunasan_uang_muka` `p` join `jurnal_header` `jkk` on(`jkk`.`id` = `p`.`jurnal_uang_muka_id`)) join `jurnal_header` `jp` on(`jp`.`id` = `p`.`jurnal_biaya_id`)) left join `m_akun_gl` `akun` on(`akun`.`id` = `p`.`akun_biaya_id`)) left join (select `jurnal_detail`.`jurnal_id` AS `jurnal_id`,`jurnal_detail`.`akun_id` AS `akun_id`,sum(`jurnal_detail`.`debit`) AS `total_debit`,sum(`jurnal_detail`.`kredit`) AS `total_kredit` from `jurnal_detail` group by `jurnal_detail`.`jurnal_id`,`jurnal_detail`.`akun_id`) `jd` on(`jd`.`jurnal_id` = `p`.`jurnal_biaya_id` and `jd`.`akun_id` = `p`.`akun_biaya_id`)) where `jkk`.`jenis` = 'JKK';

